-- 147 | 2026-11-21 | Soc Trang OLD round 2: Chau Thanh gap + rural bookshop supplements.
-- Public listing and tax registry research only, never mark visited/GPS/active retail.
WITH src AS(SELECT x.*,md5('fbmn:soctrang-old:round02:'||x.source_key) dg
 FROM jsonb_to_recordset('[{"district":"Huyện Châu Thành","name":"Nhà sách Ngọc Thanh","address_line":"493 ấp Trà Quýt A, thị trấn Châu Thành cũ, huyện Châu Thành, Sóc Trăng","category":"nha_sach","phone":null,"tax_code":null,"source_key":"contact:ngocthanh:493-traquytA","source_url":"https://vietnam.contact.page/locations/vn-vi48-so-c-tra-ng/listings?page=12","verification_note":"Danh bạ địa chỉ 493 ấp Trà Quýt A, thị trấn Châu Thành cũ; chưa có điện thoại và chưa Sales xác minh còn hoạt động."},{"district":"Huyện Châu Thành","name":"Hộ kinh doanh nhà sách Phương Thảo","address_line":"201 ấp Trà Quýt A, thị trấn Châu Thành cũ, huyện Châu Thành, Sóc Trăng","category":"nha_sach","phone":null,"tax_code":"8368298733001","source_key":"tax:8368298733-001:phuongthao-chauthanh","source_url":"https://masothue.com/8368298733-001-ho-kinh-doanh-nha-sach-phuong-thao","verification_note":"MST và địa chỉ có trong danh bạ thuế; chỉ có hồ sơ hộ kinh doanh, CHƯA chứng minh quầy sách còn mở; không khẳng định đã bán lẻ năm 2026."},{"district":"Huyện Kế Sách","name":"LEDO Books","address_line":"Ấp Đông Hải, xã Đại Hải cũ, huyện Kế Sách, Sóc Trăng","category":"nha_sach","phone":null,"tax_code":null,"source_key":"happynewday:ledo-books:apdonghai-daihai","source_url":"https://happynew.day/vendor/ledo-books","verification_note":"Danh bạ xác định địa bàn Kế Sách và chuyên mục nhà sách; chưa có số nhà, cần xác minh cửa hàng."},{"district":"Huyện Mỹ Xuyên","name":"Hiệu Sách Thông Minh - Smart Book Store","address_line":"Đường Lê Lợi, thị trấn Mỹ Xuyên cũ, huyện Mỹ Xuyên, Sóc Trăng","category":"nha_sach","phone":null,"tax_code":null,"source_key":"happynewday:smart-book-store:leloi-myxuyen","source_url":"https://happynew.day/s/vn/52/","verification_note":"Danh bạ HappyNew.Day có tiệm sách đường Lê Lợi Mỹ Xuyên, chưa có số nhà/điện thoại, cần Sales xác minh."}]'::jsonb) AS x(
 district text,name text,address_line text,category text,phone text,tax_code text,source_key text,source_url text,verification_note text)),
 ins AS(INSERT INTO public.field_prospects(id,area_visit_id,owner_sub,name,address_line,province,district,category,phone,tax_code,note,status,source_kind,research_source_key,research_source_url,research_batch)
 SELECT (substr(s.dg,1,8)||'-'||substr(s.dg,9,4)||'-5'||substr(s.dg,14,3)||'-8'||substr(s.dg,18,3)||'-'||substr(s.dg,21,12))::uuid,
 NULL,'ef943de4-18f7-49ef-8340-eefb18855534',s.name,s.address_line,'Sóc Trăng',s.district,s.category,s.phone,s.tax_code,
 'Vòng rà bù nguồn công khai 21/11/2026; CHƯA GHÉ; GPS chưa xác minh; chưa xác minh hoạt động bán lẻ. '||s.verification_note||' Nguồn: '||s.source_url,
 'new','manual',s.source_key,s.source_url,'2026-11-21-soc-trang-old-round02-gaps-01'
 FROM src s WHERE s.district IN ('Huyện Châu Thành','Huyện Kế Sách','Huyện Mỹ Xuyên') AND s.source_url LIKE 'https://%'
 AND NOT EXISTS(SELECT 1 FROM customers c WHERE c.province='Sóc Trăng' AND c.district=s.district AND
 (lower(trim(c.name))=lower(trim(s.name)) OR (c.phone IS NOT NULL AND s.phone IS NOT NULL AND c.phone=s.phone)))
 AND NOT EXISTS(SELECT 1 FROM field_prospects p WHERE p.province='Sóc Trăng' AND p.district=s.district AND
 (p.research_source_key=s.source_key OR (lower(trim(p.name))=lower(trim(s.name)) AND lower(trim(p.address_line))=lower(trim(s.address_line)))
 OR (p.phone IS NOT NULL AND s.phone IS NOT NULL AND p.phone=s.phone) OR (p.tax_code IS NOT NULL AND s.tax_code IS NOT NULL AND p.tax_code=s.tax_code)))
 ON CONFLICT(research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING RETURNING district,category,phone,tax_code)
 SELECT district,count(*)::int inserted,count(*) FILTER(WHERE category='nha_sach')::int bookstores,count(*) FILTER(WHERE tax_code IS NOT NULL)::int taxes FROM ins GROUP BY district ORDER BY district;